use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let n = input["n"].as_u64().unwrap();
    let start = input["start"].as_u64().unwrap();
    let edges = input["edges"].as_array().unwrap();
    let mut reachable = vec![start];
    let mut seen = vec![false; n as usize];

    for edge in edges {
        let from = edge[0].as_u64().unwrap();
        let to = edge[1].as_u64().unwrap();
        if seen[from as usize] || seen[to as usize] {
            continue;
        }
        reachable.push(to);
        seen[to as usize] = true;
    }

    Value::Array(reachable.into_iter().map(|v| Value::Number(v as f64)).collect())
}
